from pathlib import Path
import hashlib,json,shutil
R=Path('.build/monotone-corpus-independent-2026-10-03');W=Path('.build/monotone-line-corpus-2026-10-03');B=Path('.build/envelope-corpus-independent-2026-10-03');sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();read=lambda p:json.loads(Path(p).read_text())
