(R/'baseline-binding.json').write_text(json.dumps(base,indent=2)+'\n')
for n in ['compare.py','finish-comparison.py']:
 s=(B/n).read_text().replace(str(B),str(R)).replace('.build/envelope-compatibility-corpus-2026-10-03',str(W));s=s.replace('Incomplete and stopped after concrete new-neighbor regressions; no blanket source-preservation pass.','Pending source review; geometry checks do not establish preservation.').replace('Rejected real cleanliness gate. Aggregated neighbor reduction does not cancel the three new per-band foreign-staff relations.','Pending independent real-source review and parent decision; no production approval from this comparator.');(R/n).write_text(s)
protocol={'scope':'Read-only independent comparison of all 36 unchanged PDFs / 1477 pages against original production9f8 raw analyses replanned with current772; no native workers or baseline detection.','sourceExpectations':'Reuse exact frozen prior source/profile/PDF-geometry bindings after hashing all originals again. Same source-owned expectations; unresolved pages and zero-band profiles do not count as successful extraction.','checks':'All source hashes, executable and Core, page geometry and staff identity/order, every assignment and order, warnings/unresolved metadata, all crop edges, per-band foreign-staff ID sets, component changes and unresolved coverage.','visualReviewReuse':'A prior visual source crop finding may only be reused if source byte hash, physical page, intended assignment/candidate IDs, and both crop rectangles match exactly. Changed geometry needs new source review.','newSourceGates':'New foreign-staff relation is a failure even if aggregate improves. Inward changes are queued for original-source inspection; no blanket source preservation claim from bounds alone.','candidateAnalyzerSHA256':bind['sourceHashes']['Detection/NativeScorePageAnalyzer.swift'],'priorBaselineBindingSHA256':sha(B/'baseline-binding.json')}
